    : !paused && tabContextTimeSec === null && timelineFollowNow;
  const activeManualTimelineWindowEndSec = dashboardTimeContextActive
    ? dashboardContextTimeSec
    : tabContextTimeSec ?? manualTimelineWindowEndSec;

  const {
    streams,
    interfaces,
    timeline,
    timelineWindow,
    timelineAvailable,
    timelineSource,
    timelineLoading,
    summary,
    liveSummary,
    selectedListItem,
