}

.menu-item-copy small {
  font-size: var(--font-size-xs);
}

.app-context-bar {
  min-width: 0;
  min-height: var(--context-bar-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: 0 var(--space-3);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.app-context-identity,
.app-context-status {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.app-context-icon {
  flex: 0 0 auto;
  color: var(--muted);
}

.app-context-identity strong {
  color: var(--text-strong);
  font-size: var(--font-size-sm);
  letter-spacing: -.01em;
  white-space: nowrap;
}

.app-context-identity span {
  overflow: hidden;
  color: var(--muted);
  font-size: var(--font-size-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.status-badge,
.context-live-toggle,
.context-theme-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-muted);
  color: var(--muted);
  font-size: var(--font-size-xs);
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
}

.status-badge {
  padding: 0 7px;
}

.status-badge-success {
  border-color: color-mix(in srgb, var(--success) 42%, var(--line));
  background: var(--success-soft);
  color: var(--success);
}

.status-badge-warning {
  border-color: color-mix(in srgb, var(--warning) 42%, var(--line));
  background: var(--warning-soft);
  color: var(--warning);
}

.status-badge-accent {
  border-color: var(--accent-border);
  background: var(--accent-soft);
  color: var(--accent);
}

.context-live-toggle,
.context-theme-toggle {
  cursor: pointer;
  padding: 0 8px;
}

.context-live-toggle > span {
  width: 6px;
  height: 6px;
  margin-right: 5px;
  border-radius: 50%;
  background: currentColor;
}

.context-live-toggle.is-success {
  border-color: color-mix(in srgb, var(--success) 42%, var(--line));
  background: var(--success-soft);
  color: var(--success);
}

.context-live-toggle.is-warning {
  border-color: color-mix(in srgb, var(--warning) 42%, var(--line));
  background: var(--warning-soft);
  color: var(--warning);
}

.context-live-toggle:hover,
.context-theme-toggle:hover {
  border-color: var(--accent-border);
  color: var(--accent);
}

.main-tab-view,
.dashboard-view {
  padding: var(--space-3);
}

.main-tab-view {
  padding-top: var(--space-3);
}

.app-context-bar-compact {
  margin-bottom: var(--space-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
}

