  cursor: pointer;
  transition: background .16s ease, border-color .16s ease, color .16s ease, transform .16s ease;
}
.live-toggle:hover { transform: translateY(-1px); }
.live-toggle.live {
  border-color: rgba(86,243,154,.45);
  color: #56f39a;
}
.live-toggle.live:hover {
  background: rgba(86,243,154,.08);
}
.live-toggle.paused {
  border-color: rgba(247,200,115,.42);
  color: #f7c873;
}
.live-toggle.paused:hover {
  background: rgba(247,200,115,.08);
}
.status-strip strong { display: block; font-size: 14px; letter-spacing: .01em; }
.status-strip span:not(.live-badge) { display: block; margin-top: 3px; color: var(--muted); font-size: 12px; }
@media (max-width: 900px) {
  .compact-header { align-items: stretch; }
  .status-strip { min-width: 0; }
}
/* Sharper radius and tree toggle alignment refinement */
.hero-panel,
.list-pane,
.detail-pane { border-radius: 10px; }
.summary-card,
.stat-card,
.chart-card,
.flow-table-card,
.metric-group,
.stats-section,
/*.more-metrics { border-radius: 7px; }*/
.more-metrics { border-radius: 4px; }
.stream-tree,
.stream-row,
.flow-list-row,
.flow-row,
.list-toolbar input,
/*.kind-pill { border-radius: 5px; }*/
.kind-pill { border-radius: 4px; }
.sparkline-empty { border-radius: 4px; }
/*.tree-toggle { width: 20px; height: 20px; border-radius: 4px; align-self: center; transform-origin: 50% 50%; font-size: 0; }*/
.tree-toggle { width: 20px; height: 20px; border-radius: 2px; align-self: center; transform-origin: 50% 50%; font-size: 0; }
/*.tree-toggle.expandable { font-size: 24px; line-height: 18px; font-weight: 700; padding-bottom: 2px; }*/
/*.tree-toggle.expandable { font-size: 18px; line-height: 18px; font-weight: 700; padding-bottom: 2px; color: #d7e3ee; }*/
/*.tree-toggle.expandable { font-size: 18px; line-height: 18px; font-weight: 700; padding-bottom: 2px; color: var(--muted); }*/
/*.tree-toggle.expandable { font-size: 18px; line-height: 18px; font-weight: 700; padding-bottom: 0px; color: var(--muted); }*/
/*.tree-toggle.expandable { font-size: 24px; line-height: 18px; font-weight: 700; padding-bottom: 0px; color: var(--muted); }*/
.tree-toggle.expandable {
/*  font-size: 32px;*/
  font-size: 18px;
  line-height: 18px;
  font-weight: 700;
  color: var(--muted);
  padding-top: 0px;
/*  padding-left: 6px;*/
/*  padding-left: 6px;*/
/*  padding-right: 18px;*/
/*  padding-bottom: 24px;*/
  padding-left: 5px;
  padding-right: 17px;
  padding-bottom: 22px;
}
.tree-toggle.open { transform: rotate(90deg); }
/* Compact stats in detail pane */
.stats-section { padding: 9px; }
.stats-section h3 { margin-bottom: 6px; font-size: 14px; }
.stats-grid { gap: 6px; margin-bottom: 0; }
.stats-section .stat-card { padding: 8px 9px; }
.stats-section .stat-card span { font-size: 10px; line-height: 1.1; }
.stats-section .stat-card strong { margin-top: 3px; font-size: 15px; line-height: 1.1; }
/* Keep compact stats layout but restore readable typography */
.stats-section .stat-card span { font-size: 12px; line-height: 1.15; }
.stats-section .stat-card strong { font-size: 18px; line-height: 1.15; }
/* Match Stats heading size with other detail section headings */
.stats-section h3 { font-size: inherit; line-height: normal; margin-bottom: 8px; }
/* Keep chart DOM height stable during realtime updates */
.chart-card { position: relative; overflow-anchor: none; min-width: 0; }
.chart-host { width: 100%; min-width: 0; overflow: hidden; }
.chart-empty-overlay { position: absolute; left: 14px; right: 14px; bottom: 14px; pointer-events: none; }
.detail-pane { overflow-anchor: none; }
.search-box { position: relative; display: block; }
.search-box > span { position: absolute; left: 12px; top: 50%; transform: translateY(-52%); color: var(--muted); font-size: 18px; line-height: 1; pointer-events: none; }
.search-box input { padding-left: 36px; padding-right: 34px; }
.search-box > span { font-size: 22px; }
.search-clear {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 22px;
  height: 22px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  display: grid;
  place-items: center;
  font-size: 18px;
  line-height: 1;
  padding: 0;
}
.search-clear:hover {
  color: #eef4fb;
  background: rgba(102,217,239,.08);
}
/*.events-card { border: 1px solid var(--line); border-radius: 7px; background: var(--panel-strong); padding: 10px; margin-bottom: 14px; }*/
.events-card { border: 1px solid var(--line); border-radius: 4px; background: var(--panel-strong); padding: 10px; margin-bottom: 14px; }

