.topology-placeholder-kicker {
  color: var(--accent);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}


/* Phase 2 visual foundation: compact observability-console theme */
body {
  font-family: "Aptos", "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg-main);
  color: var(--text);
}
button, input, select {
  font: inherit;
}
.app-main {
  background: var(--bg-main);
}
.menu-rail {
  background: var(--surface-raised);
  border-right: 1px solid var(--line);
  box-shadow: var(--shadow-sm);
  backdrop-filter: none;
}
.menu-rail-toggle,
.menu-item {
  border-radius: 6px;
  color: var(--muted);
}
.menu-rail-toggle {
  background: var(--surface-muted);
  border-color: var(--line);
}
.menu-rail-toggle:hover,
.menu-item:hover,
.menu-item.active {
  background: var(--accent-soft);
  border-color: var(--accent-border);
  color: var(--text-strong);
}
.hero-panel {
  align-items: center;
  padding: 12px 16px;
  border-radius: 0;
  background: var(--surface);
  box-shadow: var(--shadow-sm);
}
.summary-card,
.stat-card,
.list-pane,
.detail-pane,
.events-card,
.timeline-pane,
*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  min-width: 320px;
  min-height: 100%;
  overscroll-behavior-x: none;
}

body {
  margin: 0;
  background: var(--bg-main);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-compact);
}

button,
input,
select,
textarea {
  font: inherit;
  font-size: var(--font-size-sm);
}

button,
select {
  min-height: var(--control-height);
}

button:focus-visible,
input:focus-visible,
