item.stdout:
.app-frame {
  min-height: 100vh;
  background: var(--bg-main);
}

.app-main {
  grid-template-rows: var(--context-bar-height) minmax(0, 1fr);
}

.menu-rail {
  padding: var(--space-2) 0;
  gap: var(--space-2);
  background: var(--surface-raised);
  border-right-color: var(--line);
  box-shadow: none;
}

.menu-rail-toggle,
.menu-item {
  border: 0;
  border-radius: 0;
}

.menu-rail-toggle {
  height: var(--context-bar-height);
  min-height: var(--context-bar-height);
  background: transparent;
  padding: 0 18px;
}

.menu-item {
  min-height: 38px;
  padding: 0 18px;
}

.menu-rail.collapsed {
  width: 56px;
}

.menu-item:hover,
.menu-item.active {
  border-color: transparent;
}

.menu-item-copy small {
  font-size: var(--font-size-xs);
}

.app-context-bar {
  min-width: 0;
  min-height: var(--context-bar-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: 0 var(--space-3);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.app-context-identity,
.app-context-status {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.app-context-icon {
  flex: 0 0 auto;
  color: var(--muted);
}
/*  padding: 14px 10px;*/
  padding: 10px 10px;
  border-right: 1px solid var(--line);
  border-radius: 0;
  background:
    radial-gradient(circle at 50% 0%, rgba(102,217,239,.14), transparent 32%),
    linear-gradient(180deg, rgba(12, 23, 34, .96), rgba(17, 24, 34, .88));
  box-shadow: 0 20px 64px rgba(0,0,0,.22);
  backdrop-filter: blur(18px);
  transition: width .18s ease, padding .18s ease;
}
.menu-rail.collapsed { width: 72px; }
.menu-rail.expanded { width: 220px; }
.menu-rail-toggle {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 42px;
  padding: 0 10px;
  border: 1px solid rgba(143, 164, 188, .18);
/*  border-radius: 10px;*/
/*  border-radius: 4px;*/
  border-radius: 3px;
  background: rgba(255,255,255,.03);
  color: var(--text-strong);
  cursor: pointer;
}
.menu-rail-toggle:hover { background: rgba(102,217,239,.08); border-color: rgba(102,217,239,.24); }
.menu-rail-toggle-icon {
  display: grid;
  place-items: center;
  width: 20px;
  color: var(--accent);
  font-size: 16px;
  line-height: 1;
}
.menu-rail-brand {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.menu-rail-nav {
  display: grid;
  gap: 8px;
  align-content: start;
}
.menu-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 48px;
  padding: 0 10px;
  border: 1px solid transparent;
/*  border-radius: 10px;*/
/*  border-radius: 4px;*/
  border-radius: 3px;
  background: transparent;
  color: var(--muted);
  text-align: left;
  cursor: pointer;
}
.menu-item:hover,
.menu-item.active {
  background: rgba(102,217,239,.08);
  border-color: rgba(102,217,239,.16);
  color: #eef4fb;
}
.menu-item-icon {
  display: grid;
  place-items: center;
  width: 20px;
  flex: 0 0 20px;
  color: var(--accent);
  font-size: 17px;
  line-height: 1;
}
.menu-item-copy strong {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: inherit;
}
.menu-item-copy small {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 10px;
}
.hero-panel { display: flex; align-items: end; justify-content: space-between; gap: 18px; padding: 22px; border: 1px solid var(--line); border-radius: 28px; background: linear-gradient(135deg, rgba(14,29,43,.9), rgba(37,28,18,.72)); box-shadow: 0 20px 64px rgba(0,0,0,.28); }
.eyebrow { margin: 0 0 8px; color: var(--accent); text-transform: uppercase; letter-spacing: .16em; font-size: 12px; }
.uplot { background: transparent; color: #dfe8f2; }
.uplot .u-title { color: #dfe8f2; }
.uplot .u-legend { color: #dfe8f2; background: transparent; }

@media (max-width: 1100px) {
  .app-frame { grid-template-columns: 1fr; }
  .app-shell { padding: 12px; }
  .app-main {
    min-height: 0;
    padding: 0;
    overflow: visible;
  }
  .menu-rail {
    position: static;
    min-height: 0;
    width: 100%;
    border: 1px solid var(--line);
    border-radius: 16px;
  }
  .menu-rail.collapsed,
  .menu-rail.expanded { width: 100%; }
  .menu-rail-nav {
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  }
  .hero-panel { align-items: stretch; flex-direction: column; }
  .workspace { grid-template-columns: 1fr; }
  .detail-pane { max-height: none; }
  .detail-body { overflow: visible; }

