import type { ReactNode } from "react";
import { Icon, type IconName } from "./Icon";

type PaneHeaderProps = {
  title?: ReactNode;
  meta?: ReactNode;
  actions?: ReactNode;
  className?: string;
  icon?: IconName;
};

export function PaneHeader({ title, meta, actions, className = "", icon }: PaneHeaderProps) {
  return (
    <header className={`pane-header ${className}`.trim()}>
      {(title || meta) && (
        <div className="pane-header-copy">
          {icon && <Icon className="pane-header-icon" name={icon} size={14} />}
          {title && <strong className="pane-header-title">{title}</strong>}
          {meta && <span className="pane-header-meta">{meta}</span>}
        </div>
      )}
      {actions && <div className="pane-header-actions">{actions}</div>}
    </header>
  );
}


type PaneFrameProps = {
  header: ReactNode;
  children: ReactNode;
  className?: string;
};

export function PaneFrame({ header, children, className = "" }: PaneFrameProps) {
  return (
    <section className={("pane-frame " + className).trim()}>
      {header}
      <div className="pane-body">{children}</div>
    </section>
  );
}
.pane-header {
  min-height: var(--pane-header-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  padding: 0 var(--space-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.pane-header-copy,
.pane-header-actions {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.pane-header-icon {
  flex: 0 0 auto;
  color: var(--muted);
}

.pane-header-title-with-icon {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
}

.pane-header-title {
  color: var(--text-strong);
  font-size: var(--font-size-sm);
  white-space: nowrap;
}

.pane-header-meta {
  overflow: hidden;
  color: var(--muted);
  font-size: var(--font-size-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.search-input {
  position: relative;
  display: block;
  min-width: 0;
}

.search-input > svg {
  position: absolute;
  top: 50%;
  left: 9px;
  color: var(--muted);
  font-size: var(--font-size-md);
  line-height: 1;
  pointer-events: none;
  transform: translateY(-50%);
}

.search-input input {
  width: 100%;
  min-height: var(--control-height);
  padding: 0 30px 0 28px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface-muted);
  color: var(--text-strong);
}

.search-input .search-clear {
  right: 5px;
  width: 20px;
  height: 20px;
  min-height: 20px;
  font-size: var(--font-size-md);
}

.list-toolbar,
.timeline-header,
.events-header,
.detail-header,
.topology-header,
.dashboard-toolbar {
  min-height: var(--pane-header-height);
}

.list-toolbar h2,
.timeline-header h3,
.events-header h3,
.topology-header h2,
.dashboard-toolbar h2 {
  margin: 0;
  color: var(--text-strong);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-compact);
}

.list-toolbar p,
.timeline-header p,
.topology-header p,
.dashboard-toolbar p {
  margin: 0;
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.dashboard-toolbar {
  margin: 0;
}

/* A tab and a dashboard cell share the same flat header/body boundary. */
.main-tab-view {
  min-height: 0;
  height: 100%;
  padding: var(--space-3);
  overflow: hidden;
}

.main-tab-view > .pane-frame,
.main-tab-view > .standalone-view {
  min-height: 0;
  height: 100%;
}

.pane-frame {
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: var(--pane-header-height) minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.pane-frame > .pane-header {
  min-height: var(--pane-header-height);
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
}

.pane-body {
  min-height: 0;
  overflow: hidden;
  background: var(--surface);
}

.pane-header-actions {
  justify-content: flex-end;
  flex-wrap: wrap;
  margin-left: auto;
}

.pane-search {
  width: min(240px, 26vw);
}

.streams-tab-frame .pane-body,
.timeline-tab-frame .pane-body {
  display: grid;
}

.streams-tab-frame .stream-table,
.timeline-tab-frame .pane-timeline-body {
  min-height: 0;
  height: 100%;
}

.timeline-tab-frame .pane-timeline-body {
  overflow: auto;
}

@media (max-width: 900px) {
  .pane-header-meta {
    display: none;
  }

  .pane-search {
    width: min(190px, 38vw);
  }

  .stream-tab-actions,
  .timeline-tab-actions {
    gap: var(--space-1);
  }
}
.app-frame {
  min-height: 100vh;
  background: var(--bg-main);
}

.app-main {
  grid-template-rows: var(--context-bar-height) minmax(0, 1fr);
}

.menu-rail {
  padding: var(--space-2) 0;
  gap: var(--space-2);
  background: var(--surface-raised);
  border-right-color: var(--line);
  box-shadow: none;
}

.menu-rail-toggle,
.menu-item {
  border: 0;
  border-radius: 0;
}

.menu-rail-toggle {
  height: var(--context-bar-height);
  min-height: var(--context-bar-height);
  background: transparent;
  padding: 0 18px;
}

.menu-item {
  min-height: 48px;
  padding: 0 18px;
}

.menu-rail-nav {
  gap: 0;
}

.menu-rail.collapsed {
  width: 56px;
}

@media (max-width: 1100px) {
  .menu-rail.collapsed,
  .menu-rail.expanded {
    width: 100%;
  }
}

.menu-item:hover,
.menu-item.active {
  border-color: transparent;
}

.menu-item-copy small {
  font-size: var(--font-size-xs);
}

.app-context-bar {
  min-width: 0;
  min-height: var(--context-bar-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: 0 var(--space-3);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.app-context-identity,
.app-context-status {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.app-context-icon {
  flex: 0 0 auto;
  color: var(--muted);
}

.app-context-identity strong {
  color: var(--text-strong);
  font-size: var(--font-size-sm);
  letter-spacing: -.01em;
  white-space: nowrap;
}

.app-context-identity span {
  overflow: hidden;
  color: var(--muted);
  font-size: var(--font-size-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.status-badge,
.context-live-toggle,
.context-theme-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-muted);
  color: var(--muted);
  font-size: var(--font-size-xs);
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
}

.status-badge {
  padding: 0 7px;
}

