                      rows={filteredTimeline}
                      gaps={timelineGaps}
                      nowSec={tabContextTimeSec ?? summary.updatedAt ?? Date.now() / 1000}
                      fadeSec={appConfig.lostRetentionSec}
                      rangeStartSec={timelineWindow.from}
                      rangeEndSec={timelineWindow.to}
                      expandLevel={timelineExpandLevel}
                      selectedTimeSec={tabContextTimeSec}
                      onSelectTime={selectGlobalTime}
                      interfaceNames={timelineInterfaceNames}
                    />
                    <div className="timeline-scrollbar">
                      <input
                        type="range"
                        min={0}
                        max={Math.max(1, timelineScrollbarMax)}
                        step={Math.max(1, Math.round(timelineWindowSec / 120))}
                        value={timelineScrollbarMax === 0 ? 0 : timelineScrollbarValue}
                        disabled={!enableTimelineBrowse}
                        onChange={(event) => {
                          const offset = Number(event.target.value);
                          setTimelineFollowNow(false);
                          setManualTimelineWindowEndSec(timelineAvailable.from + offset + timelineWindowSec);
                        }}
                      />
                    </div>
                  </div>
                </PaneFrame>
              )}
              {activeTab === "topology" && (
                <section className="standalone-view topology-tab-view">
                  <TopologyPane
                    selectedTimeSec={tabContextTimeSec}
                    onSelectStream={(streamKey) => {
                      setSelectedInterfaceKey(null);
                      setSelectedStreamKey(streamKey);
                      setSelectedFlowKey(null);
                    }}
                    onSelectFlow={(streamKey, flowKey) => {
                      setSelectedInterfaceKey(null);
                      setSelectedStreamKey(streamKey);
                      setSelectedFlowKey(flowKey);
                    }}
                    onSelectTime={selectGlobalTime}
                  />
                </section>
              )}
              {activeTab === "events" && (
                <section className="standalone-view standalone-events">
                  <EventLog
                    events={events}
                    eventsRange={eventsRange}
                    onChangeEventsRange={setEventsRange}
                    selectedStreamKey={selectedStreamKey}
                    selectedFlowKey={selectedFlowKey}
                    selectedInterfaceId={selectedInterface?.interfaceId ?? null}
                    selectedTimeSec={tabContextTimeSec}
                    onSelectTime={selectGlobalTime}
                  />
                </section>
              )}
              {activeTab === "maintenance" && (
                <MaintenancePane
                  refreshToken={maintenanceRefreshToken}
                  onApplied={(nextConfig) => setAppConfig(nextConfig)}
                />
              )}
              {activeTab === "alerts" && <AlertsPane />}
              {activeTab === "protocol-map" && <ProtocolMapPane />}
            </section>
          )}
        </div>
      </div>
      {/* Strong guard against browser history swipe gestures during splitter drags; remove if it interferes with normal dragging. */}
