import { StatusBadge } from "./StatusBadge";
import { Icon, type IconName } from "./Icon";
import { useI18n } from "../../i18n";

type AppContextBarProps = {
  title?: string;
  icon?: IconName;
  updatedLabel: string;
  socketState: string;
  totalStreams?: number;
  liveLabel: string;
  liveTone: "success" | "warning";
  onToggleLive: () => void;
  onToggleTheme: () => void;
  theme: "light" | "dark";
  compact?: boolean;
};

export function AppContextBar({
  title,
  icon,
  updatedLabel,
  socketState,
  totalStreams,
  liveLabel,
  liveTone,
  onToggleLive,
  onToggleTheme,
  theme,
  compact = false
}: AppContextBarProps) {
  const { locale, locales, setLocale, t } = useI18n();
  return (
    <header className={`app-context-bar ${compact ? "app-context-bar-compact" : ""}`}>
      <div className="app-context-identity">
        {icon && <Icon className="app-context-icon" name={icon} size={14} />}
        <strong>{title ?? t("app.title")}</strong>
        <span>{updatedLabel}</span>
      </div>
      <div className="app-context-status" aria-label={t("header.applicationStatus")}>
        {totalStreams !== undefined && <StatusBadge>{t("header.streamCount", { count: totalStreams })}</StatusBadge>}
        <StatusBadge>{socketState}</StatusBadge>
        <button type="button" className={`context-live-toggle is-${liveTone}`} onClick={onToggleLive} title={t("header.liveToggle")}>
          <span aria-hidden="true" />
          {liveLabel}
        </button>
        <label className="sr-only" htmlFor="context-language">{t("header.language")}</label>
        <select id="context-language" className="context-language-select" value={locale} onChange={(event) => setLocale(event.target.value)} aria-label={t("header.language")}>
          {locales.map((item) => <option key={item.code} value={item.code}>{item.nativeName}</option>)}
        </select>
        <button
          type="button"
          className="context-theme-toggle icon-only"
          onClick={onToggleTheme}
          title={theme === "light" ? t("header.switchDark") : t("header.switchLight")}
          aria-label={theme === "light" ? t("header.switchDark") : t("header.switchLight")}
        >
          <Icon name={theme === "light" ? "themeDark" : "themeLight"} size={16} />
        </button>
      </div>
    </header>
  );
}
