  const startResizeWidth = (event: React.PointerEvent<HTMLDivElement>) => {
    if (!wideLayout) return;
    event.preventDefault();
    event.stopPropagation();
    const startX = event.clientX;
    const startWidth = rightPaneWidth;
    const width = workspaceRef.current?.clientWidth ?? workspaceWidth;
    event.currentTarget.setPointerCapture(event.pointerId);
    document.body.classList.add("is-resizing-pane");
    setResizingPane("width");

    const onMove = (moveEvent: PointerEvent) => {
      moveEvent.preventDefault();
      const maxWidth = Math.max(MIN_RIGHT_WIDTH, width - 8);
      const next = Math.min(maxWidth, Math.max(MIN_RIGHT_WIDTH, startWidth - (moveEvent.clientX - startX)));
      setRightPaneWidth(next);
      if (next > MIN_RIGHT_WIDTH && next < maxWidth) setRightPaneRestoreWidth(next);
    };
    const onUp = () => {
      document.body.classList.remove("is-resizing-pane");
      setResizingPane(null);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  const isLatestAvailable = latestAvailableTimeSec !== null;
  const contextTimeSec = dashboardTimeContextActive ? dashboardContextTimeSec : tabContextTimeSec;
  const contextPaused = dashboardTimeContextActive ? dashboardPaused : paused;
  const contextStateLabel = dashboardTimeContextActive && dashboardSelectedTimeSec !== null
    ? " · " + formatTimeTravel(dashboardSelectedTimeSec, locale)
    : !dashboardTimeContextActive && selectedTimeSec !== null
      ? " · " + formatTimeTravel(selectedTimeSec, locale)
      : contextPaused
