        : isLatestAvailable
          ? " · " + t("common.latestAvailable")
          : !summary.updatedAt
            ? " · " + t("common.waitingForData")
            : "";
  const contextUpdatedLabel = t("header.updated", { time: summary.updatedAt ? formatRelativeTime(summary.updatedAt, locale) : t("common.waiting") }) + contextStateLabel;
  const liveLabel = dashboardTimeContextActive && dashboardSelectedTimeSec !== null
    ? t("common.timeTravel")
    : !dashboardTimeContextActive && selectedTimeSec !== null
      ? t("common.timeTravel")
      : contextPaused
