import { useEffect, useMemo, useRef, useState } from "react";
import { getBootstrap, getEvents, getInterfaceMetricsByKey, getLiveStatus, getStream, getStreamMetrics, getStreamsSnapshotAt, getTimeline } from "../api/client";
import type { MetricsRangeQuery } from "../api/client";
import type { EventLogItem, InterfaceListItem, InterfaceMetricsResponse, StreamListItem, StreamMetricsResponse, StreamState, Summary, TimelineRow, TimelineWindow, WsMessage } from "../types/api";
import type { TimelineDataGap } from "../types/api";
import { useResourceLoadState } from "./useResourceLoadState";

const TIMELINE_QUERY_CHUNK_SEC = 30 * 60;
const TIMELINE_FOLLOW_REFRESH_MS = 5000;
const TIMELINE_DELTA_LOOKBACK_SEC = 120;
const STREAMS_PATCH_APPLY_MS = 2000;
const ENABLE_STREAMS_FULL_UPDATE = false;
const MAX_EVENTS_IN_MEMORY = 8000;

const limitEvents = (items: EventLogItem[]) => items.slice(0, MAX_EVENTS_IN_MEMORY);

export function useStreams(
  selectedStreamKey: string | null,
  selectedInterfaceKey: string | null,
  paused: boolean,
  selectedMetricsRange: string,
  selectedTimelineRange: string,
  selectedEventsRange: string,
  timelineFollowNow: boolean,
  manualTimelineWindowEndSec: number | null,
  streamSortRefreshToken: number,
  selectedTimeSec: number | null,
  onDefaultSelect?: (streamKey: string) => void,
  onConfigUpdate?: (config: import("../types/api").AppConfig) => void
) {
  const [streams, setStreams] = useState<StreamListItem[]>([]);
  const [interfaces, setInterfaces] = useState<InterfaceListItem[]>([]);
  const [summary, setSummary] = useState<Summary>({ totalStreams: 0, activeStreams: 0, byKind: {} });
  const [liveSummary, setLiveSummary] = useState<Summary>({ totalStreams: 0, activeStreams: 0, byKind: {} });
  const [liveUpdateReceivedAt, setLiveUpdateReceivedAt] = useState<number | null>(null);
  const [timeline, setTimeline] = useState<TimelineRow[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<EventLogItem[]>([]);
  const [timelineGaps, setTimelineGaps] = useState<TimelineDataGap[]>([]);
  const [timelineLoading, setTimelineLoading] = useState(false);
  const [historyStreamsLoading, setHistoryStreamsLoading] = useState(false);
  const [eventsLoading, setEventsLoading] = useState(false);
  const [timelineWindow, setTimelineWindow] = useState<TimelineWindow>({ from: Date.now() / 1000 - 300, to: Date.now() / 1000 });
  const [timelineAvailable, setTimelineAvailable] = useState<TimelineWindow>({ from: Date.now() / 1000 - 300, to: Date.now() / 1000 });
  const [timelineSource, setTimelineSource] = useState<"live" | "history">("history");
  const [selectedStream, setSelectedStream] = useState<StreamState | null>(null);
  const [selectedMetrics, setSelectedMetrics] = useState<StreamMetricsResponse | null>(null);
  const [selectedInterfaceMetrics, setSelectedInterfaceMetrics] = useState<InterfaceMetricsResponse | null>(null);
  const [socketState, setSocketState] = useState("connecting");
  const [events, setEvents] = useState<EventLogItem[]>([]);
  const [bootstrapped, setBootstrapped] = useState(false);
  const selectedMetricsLoad = useResourceLoadState();
  const timelineLoad = useResourceLoadState();
  const selectedInterfaceMetricsLoad = useResourceLoadState();
  const eventsLoadedRef = useRef(false);
  const socketRef = useRef<WebSocket | null>(null);
  const liveProbeObservedAtRef = useRef<number | null | undefined>(undefined);
  const onConfigUpdateRef = useRef(onConfigUpdate);
  const selectedStreamKeyRef = useRef<string | null>(selectedStreamKey);
  const selectedInterfaceKeyRef = useRef<string | null>(selectedInterfaceKey);
  const selectedMetricsRangeRef = useRef(selectedMetricsRange);
  const loadedMetricsTargetRef = useRef<string | null>(null);
  const loadedInterfaceTargetRef = useRef<string | null>(null);
  const selectedTimelineRangeRef = useRef(selectedTimelineRange);
  const selectedTimeSecRef = useRef<number | null>(selectedTimeSec);
  const pausedRef = useRef(paused);
  const reconnectTimerRef = useRef<number | null>(null);
  const previousPausedRef = useRef(paused);
  const streamSeqRef = useRef(0);
  const latestServerOrderRef = useRef<string[]>([]);
  const timelineHistoryCacheRef = useRef<{
    from: number;
    to: number;
    rows: TimelineRow[];
    available: TimelineWindow;
    gaps: TimelineDataGap[];
    source: "history" | "live";
  } | null>(null);
  const timelineLoadingRef = useRef(false);
  const patchBufferRef = useRef<{
    upserts: StreamListItem[];
    removes: string[];
    order: string[];
    interfaces: InterfaceListItem[];
    summary: Summary;
  } | null>(null);
  const patchTimerRef = useRef<number | null>(null);

  const updateLiveSummary = (next: Summary, isLiveUpdate = false) => {
    if (isLiveUpdate) setLiveUpdateReceivedAt(Date.now() / 1000);
    setLiveSummary((current) => {
      if (current.updatedAt !== undefined && (next.updatedAt === undefined || next.updatedAt < current.updatedAt)) {
        return current;
      }
      return next;
    });
  };


  useEffect(() => {
    let cancelled = false;
    const probe = () => {
      void getLiveStatus().then(({ observedAt }) => {
        if (cancelled) return;
        const previous = liveProbeObservedAtRef.current;
        liveProbeObservedAtRef.current = observedAt;
        if (observedAt !== null && previous !== undefined && previous !== null && observedAt > previous) {
          setLiveUpdateReceivedAt(Date.now() / 1000);
        }
      }).catch(() => undefined);
    };

    probe();
    const timer = window.setInterval(probe, 1000);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, []);
  useEffect(() => {
    onConfigUpdateRef.current = onConfigUpdate;
  }, [onConfigUpdate]);

  useEffect(() => {
    pausedRef.current = paused;
  }, [paused]);

  useEffect(() => {
    selectedTimeSecRef.current = selectedTimeSec;
  }, [selectedTimeSec]);

  useEffect(() => {
    selectedMetricsRangeRef.current = selectedMetricsRange;
  }, [selectedMetricsRange]);

  useEffect(() => {
    selectedTimelineRangeRef.current = selectedTimelineRange;
  }, [selectedTimelineRange]);

  useEffect(() => {
    if (paused && selectedTimeSec === null) return;
    let cancelled = false;
    let loadSeq = 0;
    let initialized = false;
    let backfillTaskSeq = 0;
    const fullLoad = () => {
      loadSeq += 1;
      const seq = loadSeq;
      if (selectedTimeSec !== null) setEventsLoading(true);
      const liveNowSec = Date.now() / 1000;
      const rangeSec = eventsRangeWindowSec(selectedEventsRange);
      const requestedTo = selectedTimeSec !== null
        ? Math.min(liveNowSec, selectedTimeSec + rangeSec / 2)
        : liveNowSec;
      const from = Math.max(0, requestedTo - rangeSec);
      const to = requestedTo;
      const isLongRange = rangeSec > 3600;

      if (!isLongRange) {
        backfillTaskSeq += 1;
        void getEvents({
          from,
          to,
          limit: 10000
        }).then((items) => {
          if (cancelled || seq !== loadSeq) return;
          eventsLoadedRef.current = true;
          setEvents(limitEvents(items));
        }).catch(() => undefined).finally(() => {
          if (!cancelled && seq === loadSeq) setEventsLoading(false);
        });
        return;
      }

      backfillTaskSeq += 1;
      const currentBackfillSeq = backfillTaskSeq;
      const backfillFrom = from;
      let backfillCursorTo = Math.max(from, to - 3600);
      void getEvents({
        from: Math.max(from, to - 3600),
        to,
        limit: 10000
      }).then((recent) => {
        if (cancelled || seq !== loadSeq) return;
        eventsLoadedRef.current = true;
        setEvents(limitEvents(recent.sort((a, b) => b.time - a.time)));
        const runBackfill = async () => {
          while (!cancelled && seq === loadSeq && currentBackfillSeq === backfillTaskSeq && backfillCursorTo > backfillFrom) {
            const chunkTo = backfillCursorTo;
            const chunkFrom = Math.max(backfillFrom, chunkTo - 3600);
            backfillCursorTo = chunkFrom;
            const chunk = await getEvents({
              from: chunkFrom,
              to: chunkTo,
              limit: 10000
            });
            if (cancelled || seq !== loadSeq || currentBackfillSeq !== backfillTaskSeq) return;
            setEvents((current) => {
              const merged = new Map<string, EventLogItem>();
              for (const item of current) merged.set(item.id, item);
              for (const item of chunk) merged.set(item.id, item);
              return limitEvents([...merged.values()].sort((a, b) => b.time - a.time));
            });
          }
        };
        void runBackfill();
      }).catch(() => undefined).finally(() => {
        if (!cancelled && seq === loadSeq) setEventsLoading(false);
      });
    };

    const refreshIncremental = () => {
      const nowSec = selectedTimeSec ?? Date.now() / 1000;
      const rangeSec = eventsRangeWindowSec(selectedEventsRange);
      const deltaFrom = Math.max(0, nowSec - Math.min(rangeSec, 120));
      void getEvents({
        from: deltaFrom,
        to: nowSec,
        limit: 10000
      }).then((chunk) => {
        if (cancelled) return;
        eventsLoadedRef.current = true;
        setEvents((current) => {
          const merged = new Map<string, EventLogItem>();
          const cutoff = nowSec - rangeSec;
          for (const item of current) {
            if (item.time >= cutoff) merged.set(item.id, item);
          }
          for (const item of chunk) {
            if (item.time >= cutoff) merged.set(item.id, item);
          }
          return limitEvents([...merged.values()].sort((a, b) => b.time - a.time));
        });
      });
    };

    const load = () => {
      if (!initialized) {
        initialized = true;
        fullLoad();
        return;
      }
      refreshIncremental();
    };

    load();
    const timer = selectedTimeSec === null ? window.setInterval(load, selectedEventsRange === "24h" ? 15000 : 5000) : undefined;
    return () => {
      cancelled = true;
      loadSeq += 1;
      backfillTaskSeq += 1;
      if (selectedTimeSec !== null) setEventsLoading(false);
      if (timer !== undefined) window.clearInterval(timer);
    };
  }, [selectedEventsRange, selectedTimeSec, paused]);

  useEffect(() => {
    selectedInterfaceKeyRef.current = selectedInterfaceKey;
  }, [selectedInterfaceKey, selectedMetricsRange, selectedTimeSec]);

  useEffect(() => {
    void getBootstrap()
      .then((bootstrap) => {
        setStreams(bootstrap.streams);
        setInterfaces(bootstrap.interfaces);
        setSummary(bootstrap.summary);
        updateLiveSummary(bootstrap.summary);
        if (!eventsLoadedRef.current) setEvents(bootstrap.events);
        setBootstrapped(true);
        if (!selectedStreamKey && bootstrap.streams.length > 0) onDefaultSelect?.(bootstrap.streams[0].streamKey);
        latestServerOrderRef.current = bootstrap.streams.map((item) => item.streamKey);
      })
      .catch(() => undefined);
  }, []);

  useEffect(() => {
    setStreams((current) => applyServerOrder(current, latestServerOrderRef.current));
  }, [streamSortRefreshToken]);

  useEffect(() => {
    if (selectedTimeSec === null) return;
    let cancelled = false;
    setHistoryStreamsLoading(true);
    void getStreamsSnapshotAt(selectedTimeSec, {
      from: Math.max(0, selectedTimeSec - eventsRangeWindowSec(selectedEventsRange)),
      to: selectedTimeSec
    }).then((snapshot) => {
      if (cancelled) return;
      setStreams(snapshot.streams);
      setInterfaces(snapshot.interfaces);
      latestServerOrderRef.current = snapshot.streams.map((item) => item.streamKey);
      const selected = selectedStreamKey
        ? snapshot.streams.find((stream) => stream.streamKey === selectedStreamKey) ?? null
        : null;
      setSelectedStream(selected ? listItemToStreamState(selected) : null);
    }).catch(() => undefined).finally(() => {
      if (!cancelled) setHistoryStreamsLoading(false);
    });
    return () => {
      cancelled = true;
      setHistoryStreamsLoading(false);
    };
  }, [selectedTimeSec, selectedStreamKey, selectedEventsRange]);


  useEffect(() => {
    selectedStreamKeyRef.current = selectedStreamKey;
    if (!selectedStreamKey) {
      loadedMetricsTargetRef.current = null;
      setSelectedStream(null);
      setSelectedMetrics(null);
      selectedMetricsLoad.reset();
      return;
    }
    if (paused && selectedTimeSec === null) return;
    let cancelled = false;
    const targetChanged = loadedMetricsTargetRef.current !== selectedStreamKey;
    loadedMetricsTargetRef.current = selectedStreamKey;
    if (targetChanged) setSelectedMetrics(null);
    const requestId = selectedMetricsLoad.begin(targetChanged ? "loading" : "refreshing");
    const load = () => {
      const query = metricsQueryForRange(selectedMetricsRange, selectedTimeSec);
      if (selectedTimeSec !== null) {
        void getStreamMetrics(selectedStreamKey, query).then((metrics) => {
          if (cancelled) return;
          setSelectedMetrics(metrics);
          selectedMetricsLoad.succeed(requestId);
        }).catch((error) => { if (!cancelled) selectedMetricsLoad.fail(requestId, error); });
        return;
      }
      void Promise.all([getStream(selectedStreamKey), getStreamMetrics(selectedStreamKey, query)]).then(([stream, metrics]) => {
        if (cancelled) return;
        setSelectedStream(stream);
        setSelectedMetrics(metrics);
        selectedMetricsLoad.succeed(requestId);
      }).catch((error) => { if (!cancelled) selectedMetricsLoad.fail(requestId, error); });
    };
    load();
    if (selectedMetricsRange === "5m" || selectedTimeSec !== null) return () => { cancelled = true; };
    const timer = window.setInterval(() => {
      const refreshId = selectedMetricsLoad.begin("refreshing");
      void Promise.all([getStream(selectedStreamKey), getStreamMetrics(selectedStreamKey, metricsQueryForRange(selectedMetricsRange))]).then(([stream, metrics]) => {
        if (cancelled) return;
        setSelectedStream(stream); setSelectedMetrics(metrics); selectedMetricsLoad.succeed(refreshId);
      }).catch((error) => { if (!cancelled) selectedMetricsLoad.fail(refreshId, error); });
    }, 10000);
    return () => { cancelled = true; window.clearInterval(timer); };
  }, [selectedStreamKey, selectedMetricsRange, selectedTimeSec, paused]);

  useEffect(() => {
    if (selectedInterfaceKey === null) {
      loadedInterfaceTargetRef.current = null;
      setSelectedInterfaceMetrics(null);
      selectedInterfaceMetricsLoad.reset();
      return;
    }
    if (paused && selectedTimeSec === null) return;
    let cancelled = false;
    const targetChanged = loadedInterfaceTargetRef.current !== selectedInterfaceKey;
    loadedInterfaceTargetRef.current = selectedInterfaceKey;
    if (targetChanged) setSelectedInterfaceMetrics(null);
    const requestId = selectedInterfaceMetricsLoad.begin(targetChanged ? "loading" : "refreshing");
    const load = (id: number) => {
      void getInterfaceMetricsByKey(selectedInterfaceKey, metricsQueryForRange(selectedMetricsRange, selectedTimeSec)).then((metrics) => {
        if (cancelled) return;
        setSelectedInterfaceMetrics(metrics);
        selectedInterfaceMetricsLoad.succeed(id);
      }).catch((error) => { if (!cancelled) selectedInterfaceMetricsLoad.fail(id, error); });
    };
    load(requestId);
    const timer = selectedTimeSec === null ? window.setInterval(() => load(selectedInterfaceMetricsLoad.begin("refreshing")), 1000) : undefined;
    return () => { cancelled = true; if (timer !== undefined) window.clearInterval(timer); };
  }, [selectedInterfaceKey, selectedMetricsRange, selectedTimeSec, paused]);

  useEffect(() => {
    const preset = timelineRangePreset(selectedTimelineRange);
    let cancelled = false;
    const load = (background = false) => {
      if (timelineLoadingRef.current) return;
      timelineLoadingRef.current = true;
      const requestId = background ? undefined : timelineLoad.begin(timeline.length > 0 ? "refreshing" : "loading");
      if (!background) setTimelineLoading(true);
      const nowSec = Date.now() / 1000;
      const safeNow = nowSec;
      const desiredToRaw = timelineFollowNow
        ? safeNow
        : manualTimelineWindowEndSec ?? (selectedTimeSec !== null ? selectedTimeSec + preset.windowSec / 2 : safeNow);
      const desiredTo = Math.min(desiredToRaw, safeNow);
      const cache = timelineHistoryCacheRef.current;
      if (cache && (!timelineFollowNow || desiredTo <= cache.to)) {
        const cachedWindow = clampTimelineWindow({
          desiredTo,
          windowSec: preset.windowSec,
          available: cache.available,
          nowSec: safeNow
        });
        if (cachedWindow.from >= cache.from && cachedWindow.to <= cache.to) {
          setTimeline(clipTimelineRows(cache.rows, cachedWindow.from, cachedWindow.to));
          setTimelineGaps(clipTimelineGaps(cache.gaps, cachedWindow.from, cachedWindow.to));
          setTimelineWindow(cachedWindow);
          setTimelineAvailable(cache.available);
          setTimelineSource(cache.source);
          timelineLoadingRef.current = false;
          if (!background) { setTimelineLoading(false); if (requestId !== undefined) timelineLoad.succeedAfterPaint(requestId); }
          return;
        }
      }

      const desiredFrom = Math.max(0, desiredTo - preset.windowSec);
      const canServeDeltaFromCache = cache ? desiredFrom >= cache.from : false;

      if (timelineFollowNow && cache && desiredTo > cache.to && canServeDeltaFromCache) {
        const deltaFrom = Math.max(0, cache.to - TIMELINE_DELTA_LOOKBACK_SEC);
        void getTimelineChunked({
          from: deltaFrom,
          to: desiredTo,
          includeFlows: true
        }).then((response) => {
          if (cancelled) return;
          const mergedRows = mergeTimelineRows(cache.rows, response.rows);
          const mergedGaps = mergeTimelineGaps(cache.gaps, response.gaps ?? []);
          const mergedAvailable: TimelineWindow = {
            from: Math.min(cache.available.from, response.available.from),
            to: Math.max(cache.available.to, response.available.to)
          };
          const keepSpanSec = Math.max(preset.windowSec * 4, 24 * 3600);
          const trimmedFrom = Math.max(mergedAvailable.from, desiredTo - keepSpanSec);
          const trimmedRows = clipTimelineRows(mergedRows, trimmedFrom, desiredTo);
          const trimmedGaps = clipTimelineGaps(mergedGaps, trimmedFrom, desiredTo);
          timelineHistoryCacheRef.current = {
            from: trimmedFrom,
            to: desiredTo,
            rows: trimmedRows,
            gaps: trimmedGaps,
            available: mergedAvailable,
            source: response.source
          };
          const window = clampTimelineWindow({
            desiredTo,
            windowSec: preset.windowSec,
            available: mergedAvailable,
            nowSec: safeNow
          });
          setTimeline(clipTimelineRows(trimmedRows, window.from, window.to));
          setTimelineGaps(clipTimelineGaps(trimmedGaps, window.from, window.to));
          setTimelineWindow(window);
          setTimelineAvailable(mergedAvailable);
          setTimelineSource(response.source);
        }).finally(() => {
          timelineLoadingRef.current = false;
          if (!background) { setTimelineLoading(false); if (requestId !== undefined) timelineLoad.succeed(requestId); }
        });
        return;
      }

      const lookbackSec = timelineFollowNow ? preset.windowSec : preset.windowSec * 4;
      const queryFrom = Math.max(0, desiredTo - lookbackSec);
      void getTimelineChunked({
        from: queryFrom,
        to: desiredTo,
        includeFlows: true
      }).then((response) => {
        if (cancelled) return;
        timelineHistoryCacheRef.current = {
          from: queryFrom,
          to: desiredTo,
          rows: response.rows,
          gaps: response.gaps ?? [],
          available: response.available,
          source: response.source
        };
        const window = clampTimelineWindow({
          desiredTo,
          windowSec: preset.windowSec,
          available: response.available,
          nowSec: safeNow
        });
        setTimeline(clipTimelineRows(response.rows, window.from, window.to));
        setTimelineGaps(clipTimelineGaps(response.gaps ?? [], window.from, window.to));
        setTimelineWindow(window);
        setTimelineAvailable(response.available);
        setTimelineSource(response.source);
      }).finally(() => {
        timelineLoadingRef.current = false;
        if (!background) { setTimelineLoading(false); if (requestId !== undefined) timelineLoad.succeed(requestId); }
      });
    };
    load();
    const timer = timelineFollowNow && selectedTimeSec === null ? window.setInterval(() => load(true), timelineFollowRefreshMs(preset.windowSec)) : undefined;
    return () => {
      cancelled = true;
      timelineLoadingRef.current = false;
      setTimelineLoading(false);
      if (timer !== undefined) window.clearInterval(timer);
    };
  }, [selectedTimelineRange, timelineFollowNow, manualTimelineWindowEndSec, selectedTimeSec]);

  useEffect(() => {
    let cancelled = false;
    const load = () => {
      void getEvents({
        from: timelineWindow.from,
        to: timelineWindow.to,
        limit: 10_000
      }).then((items) => {
        if (!cancelled) setTimelineEvents(items);
      }).catch(() => {
        if (!cancelled) setTimelineEvents([]);
      });
    };

    load();
    const timer = timelineFollowNow && selectedTimeSec === null
      ? window.setInterval(load, timelineFollowRefreshMs(timelineWindow.to - timelineWindow.from))
      : undefined;
    return () => {
      cancelled = true;
      if (timer !== undefined) window.clearInterval(timer);
    };
  }, [timelineWindow.from, timelineWindow.to, timelineFollowNow, selectedTimeSec]);

  useEffect(() => {
    let disposed = false;

    const flushPatchedStreams = () => {
      const buffered = patchBufferRef.current;
      patchBufferRef.current = null;
      patchTimerRef.current = null;
      if (!buffered || pausedRef.current || selectedTimeSecRef.current !== null) return;
      latestServerOrderRef.current = buffered.order;
      setInterfaces(buffered.interfaces);
      setSummary(buffered.summary);
      setStreams((current) => applyStreamPatchFrozen(current, buffered.upserts, buffered.removes, buffered.order));
    };

    const connect = () => {
      const protocol = window.location.protocol === "https:" ? "wss" : "ws";
      const socket = new WebSocket(`${protocol}://${window.location.host}/ws`);
      socketRef.current = socket;
      setSocketState("connecting");

      socket.onopen = () => {
        if (disposed) return;
        setSocketState("connected");
        socket.send(JSON.stringify({ type: "stream:subscribe", streamKey: selectedStreamKeyRef.current }));
      };

      socket.onclose = () => {
        if (disposed) return;
        socketRef.current = null;
        setSocketState("closed");
        if (reconnectTimerRef.current !== null) {
          window.clearTimeout(reconnectTimerRef.current);
        }
        reconnectTimerRef.current = window.setTimeout(() => {
          reconnectTimerRef.current = null;
          if (!disposed) connect();
        }, 1000);
      };

      socket.onerror = () => {
        if (disposed) return;
        setSocketState("error");
      };

      socket.onmessage = (event) => {
        const message = JSON.parse(event.data) as WsMessage;
        if (message.type === "live:heartbeat") {
          setLiveUpdateReceivedAt(Date.now() / 1000);
          return;
        }

        if (message.type === "snapshot") {
          updateLiveSummary(message.summary);
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
          setBootstrapped(true);
          setStreams(message.streams);
          latestServerOrderRef.current = message.streams.map((item) => item.streamKey);
          setInterfaces(message.interfaces);
          setSummary(message.summary);
          streamSeqRef.current = message.streamsSeq ?? 0;
          const selectedKey = selectedStreamKeyRef.current;
          if (selectedKey) {
            const selected = message.streams.find((stream) => stream.streamKey === selectedKey) ?? null;
            setSelectedStream(selected ? listItemToStreamState(selected) : null);
          }
        }
        if (message.type === "streams:update") {
          updateLiveSummary(message.summary, true);
          if (!ENABLE_STREAMS_FULL_UPDATE) return;
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
          setBootstrapped(true);
          setStreams(message.streams);
          latestServerOrderRef.current = message.streams.map((item) => item.streamKey);
          setInterfaces(message.interfaces);
          setSummary(message.summary);
          const selectedKey = selectedStreamKeyRef.current;
          if (selectedKey) {
