        }
        if (message.type === "events:update") {
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
          setEvents((current) => {
            const merged = new Map<string, EventLogItem>();
            for (const item of message.events) merged.set(item.id, item);
            for (const item of current) merged.set(item.id, item);
            return limitEvents([...merged.values()].sort((a, b) => b.time - a.time));
