  return {
    streams,
    interfaces,
    timeline,
    timelineEvents,
    timelineWindow,
    timelineAvailable,
    timelineSource,
    timelineLoading,
    timelineLoadState: timelineLoad.state,
    historyStreamsLoading,
    eventsLoading,
    timelineGaps,
    summary,
    liveSummary,
