    selectedMetrics,
    selectedMetricsLoadState: selectedMetricsLoad.state,
    selectedInterface,
    selectedInterfaceMetricsLoadState: selectedInterfaceMetricsLoad.state,
    selectedInterfaceMetrics,
    socketState,
    events,
    bootstrapped
  };
}

function eventsRangeWindowSec(range: string) {
  switch (range) {
    case "24h":
