  const loadedInterfaceTargetRef = useRef<string | null>(null);
  const selectedTimelineRangeRef = useRef(selectedTimelineRange);
  const selectedTimeSecRef = useRef<number | null>(selectedTimeSec);
  const pausedRef = useRef(paused);
  const reconnectTimerRef = useRef<number | null>(null);
  const previousPausedRef = useRef(paused);
  const streamSeqRef = useRef(0);
  const latestServerOrderRef = useRef<string[]>([]);
  const timelineHistoryCacheRef = useRef<{
    from: number;
