          const mergedGaps = mergeTimelineGaps(cache.gaps, response.gaps ?? []);
          const mergedAvailable: TimelineWindow = {
            from: Math.min(cache.available.from, response.available.from),
            to: Math.max(cache.available.to, response.available.to)
          };
