        }
        reconnectTimerRef.current = window.setTimeout(() => {
          reconnectTimerRef.current = null;
          if (!disposed) connect();
        }, 1000);
      };

      socket.onerror = () => {
        if (disposed) return;
        setSocketState("error");
      };

      socket.onmessage = (event) => {
        const message = JSON.parse(event.data) as WsMessage;
        if (message.type === "live:heartbeat") {
          setLiveUpdateReceivedAt(Date.now() / 1000);
          return;
        }

        if (message.type === "snapshot") {
          updateLiveSummary(message.summary);
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
          setBootstrapped(true);
          setStreams(message.streams);
          latestServerOrderRef.current = message.streams.map((item) => item.streamKey);
          setInterfaces(message.interfaces);
          setSummary(message.summary);
          streamSeqRef.current = message.streamsSeq ?? 0;
          const selectedKey = selectedStreamKeyRef.current;
          if (selectedKey) {
            const selected = message.streams.find((stream) => stream.streamKey === selectedKey) ?? null;
            setSelectedStream(selected ? listItemToStreamState(selected) : null);
          }
        }
        if (message.type === "streams:update") {
          updateLiveSummary(message.summary, true);
          if (!ENABLE_STREAMS_FULL_UPDATE) return;
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
          setBootstrapped(true);
          setStreams(message.streams);
          latestServerOrderRef.current = message.streams.map((item) => item.streamKey);
          setInterfaces(message.interfaces);
          setSummary(message.summary);
          const selectedKey = selectedStreamKeyRef.current;
          if (selectedKey) {
            const selected = message.streams.find((stream) => stream.streamKey === selectedKey) ?? null;
            setSelectedStream(selected ? listItemToStreamState(selected) : null);
          }
        }
        if (message.type === "streams:patch") {
          updateLiveSummary(message.summary, true);
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
