          }
          streamSeqRef.current = message.seq;
          patchBufferRef.current = {
            upserts: message.upserts,
            removes: message.removes,
            order: message.order,
            interfaces: message.interfaces,
            summary: message.summary
          };
          if (patchTimerRef.current === null) {
            patchTimerRef.current = window.setTimeout(flushPatchedStreams, STREAMS_PATCH_APPLY_MS);
          }
        }
        if (message.type === "stream:metrics" && message.streamKey === selectedStreamKeyRef.current && selectedMetricsRangeRef.current === "5m") {
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
