import type { Server as HttpServer } from "node:http";
import { WebSocketServer, type WebSocket } from "ws";
import type { StreamStore } from "../state/store";
import type { AppConfig, WsMessage } from "../types";

export class SocketServer {
  private readonly wss = new WebSocketServer({ noServer: true });
  private readonly metricSubscriptions = new Map<WebSocket, string>();
  private pendingStreams = false;
  private maintenanceTimer: NodeJS.Timeout | null = null;
  private streamSeq = 0;
  private lastStreams = new Map<string, string>();

  constructor(
    private readonly server: HttpServer,
    private readonly store: StreamStore,
    private readonly streamsPatchIntervalMs = 250,
    private readonly maxBufferedBytes = 8 * 1024 * 1024
  ) {}

  start() {
    this.server.on("upgrade", (request, socket, head) => {
      if (request.url !== "/ws") return;
      this.wss.handleUpgrade(request, socket, head, (ws) => {
        this.wss.emit("connection", ws, request);
      });
    });

    this.wss.on("connection", (ws) => {
      this.send(ws, {
        type: "snapshot",
        streams: this.store.listStreams(),
        interfaces: this.store.listInterfaces(),
        timeline: [],
        summary: this.store.getSummary(),
        streamsSeq: this.streamSeq
      });
      ws.on("message", (raw) => this.handleClientMessage(ws, raw.toString()));
      ws.on("close", () => this.metricSubscriptions.delete(ws));
    });

    this.store.on("streams:update", () => this.scheduleStreamsUpdate());
    this.store.on("metrics:update", (streamKey: string) => this.broadcastSubscribedMetrics(streamKey));

    this.store.on("events:update", (event) => {
      this.broadcast({ type: "events:update", events: [event] });
    });

    this.maintenanceTimer = setInterval(() => this.store.tick(), 1000);
    this.maintenanceTimer.unref?.();
  }

  broadcastConfig(config: AppConfig) {
    this.broadcast({ type: "config:update", config });
  }

  broadcastLiveHeartbeat() {
    this.broadcast({ type: "live:heartbeat" });
  }


  private scheduleStreamsUpdate() {
    if (this.pendingStreams) return;
    this.pendingStreams = true;
    setTimeout(() => {
      this.pendingStreams = false;
      const streams = this.store.listStreams();
      const order = streams.map((s) => s.streamKey);
      const nextMap = new Map<string, string>();
      const upserts = [];
      for (const stream of streams) {
        const encoded = JSON.stringify(stream);
        nextMap.set(stream.streamKey, encoded);
        if (this.lastStreams.get(stream.streamKey) !== encoded) {
          upserts.push(stream);
        }
      }
      const removes: string[] = [];
      for (const key of this.lastStreams.keys()) {
        if (!nextMap.has(key)) removes.push(key);
      }
      if (upserts.length === 0 && removes.length === 0) return;
      this.lastStreams = nextMap;
      this.streamSeq += 1;
      this.broadcast({
        type: "streams:patch",
        seq: this.streamSeq,
        upserts,
        removes,
        order,
        interfaces: this.store.listInterfaces(),
        summary: this.store.getSummary()
      });
    }, Math.max(50, this.streamsPatchIntervalMs));
  }

  private broadcast(message: WsMessage) {
    const clients = [...this.wss.clients].filter((client) => client.readyState === client.OPEN);
    if (clients.length === 0) return;
    const payload = JSON.stringify(message);
    for (const client of clients) this.safeSend(client, payload);
  }

  private broadcastSubscribedMetrics(streamKey: string) {
    const clients = [...this.wss.clients].filter((client) =>
      client.readyState === client.OPEN && this.metricSubscriptions.get(client) === streamKey
    );
    if (clients.length === 0) return;

    const metrics = this.store.getMetrics(streamKey);
    if (!metrics) return;

    const payload = JSON.stringify({ type: "stream:metrics", streamKey, metrics } satisfies WsMessage);
    for (const client of clients) this.safeSend(client, payload);
  }

  private handleClientMessage(client: WebSocket, raw: string) {
    try {
      const message = JSON.parse(raw) as { type?: string; streamKey?: unknown };
      if (message.type !== "stream:subscribe") return;
      if (typeof message.streamKey === "string" && message.streamKey.length > 0) {
        this.metricSubscriptions.set(client, message.streamKey);
      } else {
        this.metricSubscriptions.delete(client);
      }
    } catch {
      // Ignore malformed client messages; the connection can continue receiving snapshots.
    }
  }

  private send(client: WebSocket, message: WsMessage) {
    if (client.readyState === client.OPEN) this.safeSend(client, JSON.stringify(message));
  }

  private safeSend(client: WebSocket, payload: string) {
    if (client.bufferedAmount > this.maxBufferedBytes) {
      this.metricSubscriptions.delete(client);
      client.terminate();
      return;
    }
    client.send(payload);
  }
}
  grid: { x: number; y: number; w: number; h: number };
  params?: Record<string, unknown>;
};

export type DashboardBreakpoint = "desktop" | "tablet" | "mobile";
export type DashboardResponsiveLayouts = Partial<Record<DashboardBreakpoint, DashboardCell[]>>;

export type DashboardLayout = {
  id: string;
  name: string;
  nameKey?: string;
  columns: number;
  rowHeight: number;
  cells: DashboardCell[];
  layouts?: DashboardResponsiveLayouts;
};

export type Summary = {
  totalStreams: number;
  activeStreams: number;
  updatedAt?: number;
  byKind: Record<string, number>;
};

export type WsMessage =
  | { type: "snapshot"; streams: StreamListItem[]; interfaces: InterfaceListItem[]; timeline: TimelineRow[]; summary: Summary; streamsSeq?: number }
  | { type: "streams:update"; streams: StreamListItem[]; interfaces: InterfaceListItem[]; summary: Summary }
  | { type: "streams:patch"; seq: number; upserts: StreamListItem[]; removes: string[]; order: string[]; interfaces: InterfaceListItem[]; summary: Summary }
  | { type: "timeline:update"; timeline: TimelineRow[] }
  | { type: "live:heartbeat" }
  | { type: "stream:metrics"; streamKey: string; metrics: StreamMetricsResponse }
  | { type: "events:update"; events: EventLogItem[] }
  | { type: "config:update"; config: AppConfig };

export type AppConfig = {
  lostRetentionSec: number;
  historyWindowSec: number;
  staleAfterSec: number;
  diagnosticLog: boolean;
  dashboardLayoutEditMode: number;
};
import { useEffect, useMemo, useRef, useState } from "react";
import { getBootstrap, getEvents, getInterfaceMetricsByKey, getLiveStatus, getStream, getStreamMetrics, getStreamsSnapshotAt, getTimeline } from "../api/client";
import type { MetricsRangeQuery } from "../api/client";
import type { EventLogItem, InterfaceListItem, InterfaceMetricsResponse, StreamListItem, StreamMetricsResponse, StreamState, Summary, TimelineRow, TimelineWindow, WsMessage } from "../types/api";
import type { TimelineDataGap } from "../types/api";
import { useResourceLoadState } from "./useResourceLoadState";

const TIMELINE_QUERY_CHUNK_SEC = 30 * 60;
const TIMELINE_FOLLOW_REFRESH_MS = 5000;
const TIMELINE_DELTA_LOOKBACK_SEC = 120;
const STREAMS_PATCH_APPLY_MS = 2000;
const ENABLE_STREAMS_FULL_UPDATE = false;
const MAX_EVENTS_IN_MEMORY = 8000;

const limitEvents = (items: EventLogItem[]) => items.slice(0, MAX_EVENTS_IN_MEMORY);

export function useStreams(
  selectedStreamKey: string | null,
  selectedInterfaceKey: string | null,
  paused: boolean,
  selectedMetricsRange: string,
  selectedTimelineRange: string,
  selectedEventsRange: string,
  timelineFollowNow: boolean,
  manualTimelineWindowEndSec: number | null,
  streamSortRefreshToken: number,
  selectedTimeSec: number | null,
  onDefaultSelect?: (streamKey: string) => void,
  onConfigUpdate?: (config: import("../types/api").AppConfig) => void
) {
  const [streams, setStreams] = useState<StreamListItem[]>([]);
  const [interfaces, setInterfaces] = useState<InterfaceListItem[]>([]);
  const [summary, setSummary] = useState<Summary>({ totalStreams: 0, activeStreams: 0, byKind: {} });
  const [liveSummary, setLiveSummary] = useState<Summary>({ totalStreams: 0, activeStreams: 0, byKind: {} });
  const [liveUpdateReceivedAt, setLiveUpdateReceivedAt] = useState<number | null>(null);
  const [timeline, setTimeline] = useState<TimelineRow[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<EventLogItem[]>([]);
  const [timelineGaps, setTimelineGaps] = useState<TimelineDataGap[]>([]);
  const [timelineLoading, setTimelineLoading] = useState(false);
  const [historyStreamsLoading, setHistoryStreamsLoading] = useState(false);
  const [eventsLoading, setEventsLoading] = useState(false);
  const [timelineWindow, setTimelineWindow] = useState<TimelineWindow>({ from: Date.now() / 1000 - 300, to: Date.now() / 1000 });
  const [timelineAvailable, setTimelineAvailable] = useState<TimelineWindow>({ from: Date.now() / 1000 - 300, to: Date.now() / 1000 });
  const [timelineSource, setTimelineSource] = useState<"live" | "history">("history");
  const [selectedStream, setSelectedStream] = useState<StreamState | null>(null);
  const [selectedMetrics, setSelectedMetrics] = useState<StreamMetricsResponse | null>(null);
  const [selectedInterfaceMetrics, setSelectedInterfaceMetrics] = useState<InterfaceMetricsResponse | null>(null);
  const [socketState, setSocketState] = useState("connecting");
  const [events, setEvents] = useState<EventLogItem[]>([]);
  const [bootstrapped, setBootstrapped] = useState(false);
  const selectedMetricsLoad = useResourceLoadState();
  const timelineLoad = useResourceLoadState();
  const selectedInterfaceMetricsLoad = useResourceLoadState();
  const eventsLoadedRef = useRef(false);
  const socketRef = useRef<WebSocket | null>(null);
  const liveProbeObservedAtRef = useRef<number | null | undefined>(undefined);
  const onConfigUpdateRef = useRef(onConfigUpdate);
  const selectedStreamKeyRef = useRef<string | null>(selectedStreamKey);
  const selectedInterfaceKeyRef = useRef<string | null>(selectedInterfaceKey);
  const selectedMetricsRangeRef = useRef(selectedMetricsRange);
  const loadedMetricsTargetRef = useRef<string | null>(null);
  const loadedInterfaceTargetRef = useRef<string | null>(null);
  const selectedTimelineRangeRef = useRef(selectedTimelineRange);
  const selectedTimeSecRef = useRef<number | null>(selectedTimeSec);
  const pausedRef = useRef(paused);
  const reconnectTimerRef = useRef<number | null>(null);
  const previousPausedRef = useRef(paused);
  const streamSeqRef = useRef(0);
  const latestServerOrderRef = useRef<string[]>([]);
  const timelineHistoryCacheRef = useRef<{
    from: number;
    to: number;
    rows: TimelineRow[];
    available: TimelineWindow;
    gaps: TimelineDataGap[];
    source: "history" | "live";
  } | null>(null);
  const timelineLoadingRef = useRef(false);
  const patchBufferRef = useRef<{
    upserts: StreamListItem[];
    removes: string[];
    order: string[];
    interfaces: InterfaceListItem[];
    summary: Summary;
  } | null>(null);
  const patchTimerRef = useRef<number | null>(null);

  const updateLiveSummary = (next: Summary, isLiveUpdate = false) => {
    if (isLiveUpdate) setLiveUpdateReceivedAt(Date.now() / 1000);
    setLiveSummary((current) => {
      if (current.updatedAt !== undefined && (next.updatedAt === undefined || next.updatedAt < current.updatedAt)) {
        return current;
      }
      return next;
    });
  };


  useEffect(() => {
    let cancelled = false;
    const probe = () => {
      void getLiveStatus().then(({ observedAt }) => {
        if (cancelled) return;
        const previous = liveProbeObservedAtRef.current;
        liveProbeObservedAtRef.current = observedAt;
        if (observedAt !== null && previous !== undefined && previous !== null && observedAt > previous) {
          setLiveUpdateReceivedAt(Date.now() / 1000);
        }
      }).catch(() => undefined);
    };
      void getEvents({
        from: timelineWindow.from,
        to: timelineWindow.to,
        limit: 10_000
      }).then((items) => {
        if (!cancelled) setTimelineEvents(items);
      }).catch(() => {
        if (!cancelled) setTimelineEvents([]);
      });
    };

    load();
    const timer = timelineFollowNow && selectedTimeSec === null
      ? window.setInterval(load, timelineFollowRefreshMs(timelineWindow.to - timelineWindow.from))
      : undefined;
    return () => {
      cancelled = true;
      if (timer !== undefined) window.clearInterval(timer);
    };
  }, [timelineWindow.from, timelineWindow.to, timelineFollowNow, selectedTimeSec]);

  useEffect(() => {
    let disposed = false;

    const flushPatchedStreams = () => {
      const buffered = patchBufferRef.current;
      patchBufferRef.current = null;
      patchTimerRef.current = null;
      if (!buffered || pausedRef.current || selectedTimeSecRef.current !== null) return;
      latestServerOrderRef.current = buffered.order;
      setInterfaces(buffered.interfaces);
      setSummary(buffered.summary);
      setStreams((current) => applyStreamPatchFrozen(current, buffered.upserts, buffered.removes, buffered.order));
    };

    const connect = () => {
      const protocol = window.location.protocol === "https:" ? "wss" : "ws";
      const socket = new WebSocket(`${protocol}://${window.location.host}/ws`);
      socketRef.current = socket;
      setSocketState("connecting");

      socket.onopen = () => {
        if (disposed) return;
        setSocketState("connected");
        socket.send(JSON.stringify({ type: "stream:subscribe", streamKey: selectedStreamKeyRef.current }));
      };

      socket.onclose = () => {
        if (disposed) return;
        socketRef.current = null;
        setSocketState("closed");
        if (reconnectTimerRef.current !== null) {
          window.clearTimeout(reconnectTimerRef.current);
        }
        reconnectTimerRef.current = window.setTimeout(() => {
          reconnectTimerRef.current = null;
          if (!disposed) connect();
        }, 1000);
      };

      socket.onerror = () => {
        if (disposed) return;
        setSocketState("error");
      };

      socket.onmessage = (event) => {
        const message = JSON.parse(event.data) as WsMessage;
        if (message.type === "live:heartbeat") {
          setLiveUpdateReceivedAt(Date.now() / 1000);
          return;
        }

        if (message.type === "snapshot") {
          updateLiveSummary(message.summary);
          if (pausedRef.current || selectedTimeSecRef.current !== null) return;
          setBootstrapped(true);
          setStreams(message.streams);
