    };
  }, [selectedEventsRange, selectedTimeSec, paused]);

  useEffect(() => {
    selectedInterfaceKeyRef.current = selectedInterfaceKey;
  }, [selectedInterfaceKey, selectedMetricsRange, selectedTimeSec]);

  useEffect(() => {
    void getBootstrap()
      .then((bootstrap) => {
        setStreams(bootstrap.streams);
        setInterfaces(bootstrap.interfaces);
        setSummary(bootstrap.summary);
        updateLiveSummary(bootstrap.summary);
        if (!eventsLoadedRef.current) setEvents(bootstrap.events);
        setBootstrapped(true);
        if (!selectedStreamKey && bootstrap.streams.length > 0) onDefaultSelect?.(bootstrap.streams[0].streamKey);
        latestServerOrderRef.current = bootstrap.streams.map((item) => item.streamKey);
      })
      .catch(() => undefined);
  }, []);

  useEffect(() => {
    setStreams((current) => applyServerOrder(current, latestServerOrderRef.current));
  }, [streamSortRefreshToken]);

  useEffect(() => {
    if (selectedTimeSec === null) return;
    let cancelled = false;
    setHistoryStreamsLoading(true);
    void getStreamsSnapshotAt(selectedTimeSec, {
      from: Math.max(0, selectedTimeSec - eventsRangeWindowSec(selectedEventsRange)),
      to: selectedTimeSec
    connect();

    return () => {
      disposed = true;
      if (patchTimerRef.current !== null) {
        window.clearTimeout(patchTimerRef.current);
        patchTimerRef.current = null;
      }
      patchBufferRef.current = null;
      if (reconnectTimerRef.current !== null) {
        window.clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      const socket = socketRef.current;
      socketRef.current = null;
      socket?.close();
    };
  }, []);

  useEffect(() => {
    const socket = socketRef.current;
    if (socket?.readyState === WebSocket.OPEN) {
      socket.send(JSON.stringify({ type: "stream:subscribe", streamKey: selectedStreamKey }));
    }
  }, [selectedStreamKey]);

  useEffect(() => {
    const resumed = previousPausedRef.current && !paused;
    previousPausedRef.current = paused;
    if (!resumed) return;

    let cancelled = false;
    void Promise.all([
      getBootstrap(),
      selectedStreamKeyRef.current ? getStream(selectedStreamKeyRef.current) : Promise.resolve(null),
      selectedStreamKeyRef.current ? getStreamMetrics(selectedStreamKeyRef.current, metricsQueryForRange(selectedMetricsRange)) : Promise.resolve(null),
      selectedInterfaceKeyRef.current ? getInterfaceMetricsByKey(selectedInterfaceKeyRef.current) : Promise.resolve(null)
    ]).then(([bootstrap, stream, metrics, interfaceMetrics]) => {
      if (cancelled) return;
      setStreams(bootstrap.streams);
      setInterfaces(bootstrap.interfaces);
      setSummary(bootstrap.summary);
      updateLiveSummary(bootstrap.summary);
      if (!eventsLoadedRef.current) setEvents(bootstrap.events);
      setSelectedStream(stream);
      setSelectedMetrics(metrics);
      setSelectedInterfaceMetrics(interfaceMetrics);
    });

    return () => {
      cancelled = true;
    };
  }, [paused, selectedMetricsRange]);

  const selectedListItem = useMemo(
    () => streams.find((stream) => stream.streamKey === selectedStreamKey) ?? null,
    [streams, selectedStreamKey]
  );

  const selectedInterface = useMemo(
    () => interfaces.find((item) => item.key === selectedInterfaceKey) ?? null,
    [interfaces, selectedInterfaceKey]
  );

