        <StatusBadge tone={connectionStatus.tone}>{connectionStatus.label}</StatusBadge>
        <button type="button" className={`context-live-toggle is-${liveTone}`} onClick={onToggleLive} title={t("header.liveToggle")}>
          <span aria-hidden="true" />
          {liveLabel}
        </button>
        <label className="sr-only" htmlFor="context-language">{t("header.language")}</label>
        <select id="context-language" className="context-language-select" value={locale} onChange={(event) => setLocale(event.target.value)} aria-label={t("header.language")}>
          {locales.map((item) => <option key={item.code} value={item.code}>{item.nativeName}</option>)}
